import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"ADRs and Key Decisions","description":"The Hearth ADR index and final decisions.","frontmatter":{"title":"ADRs and Key Decisions","description":"The Hearth ADR index and final decisions.","outline":[2,3]},"headers":[],"relativePath":"en/reference/decisions.md","filePath":"en/reference/decisions.md","lastUpdated":1793797632000}'),i={name:"en/reference/decisions.md"};function n(r,e,s,l,c,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<p class="eyebrow">DECISIONS</p><h1 id="adrs-and-key-decisions" tabindex="-1">ADRs and Key Decisions <a class="header-anchor" href="#adrs-and-key-decisions" aria-label="Permalink to &quot;ADRs and Key Decisions&quot;">​</a></h1><p class="lead">Codify product and engineering judgments that are not easily reversible into traceable decision records.</p><h2 id="adr-index" tabindex="-1">ADR Index <a class="header-anchor" href="#adr-index" aria-label="Permalink to &quot;ADR Index&quot;">​</a></h2><p>The following are the recommended first batch of architecture decisions. Those with status <code>Accepted</code> should be committed to the repository as early as possible; subsequent changes are recorded through new ADRs.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Decision</th><th>Status</th><th>Main Consequences</th></tr></thead><tbody><tr><td>ADR-001</td><td>Hearth is a single-user, self-hosted, local-first personal Agent OS</td><td><code>Accepted</code></td><td>No enterprise IAM; prioritize local state and portability</td></tr><tr><td>ADR-002</td><td>Event Log is the single source of truth; UI/indexes/memory are projections</td><td><code>Accepted</code></td><td>Requires event schema, replay, and migration</td></tr><tr><td>ADR-003</td><td>Use SQLite WAL and a single writer early on; do not introduce microservices</td><td><code>Accepted</code></td><td>Reduces operations overhead; requires leases and a horizontal scaling plan</td></tr><tr><td>ADR-004</td><td>Adopt a modular monolith; Executor integration occurs through a unified protocol</td><td><code>Accepted</code></td><td>Boundaries are enforced by interfaces and tests, not network decomposition</td></tr><tr><td>ADR-005</td><td>Use a multi-Executor model rather than pursuing a single all-purpose Agent</td><td><code>Accepted</code></td><td>Requires capability declarations, routing, and a unified result contract</td></tr><tr><td>ADR-006</td><td>Codex is the first external Executor and can handle code, research, documents, and Shell, but is not the product itself</td><td><code>Accepted</code></td><td>Requires adapters, version pinning, and fallback paths</td></tr><tr><td>ADR-007</td><td>Build Execution Gateway, Policy, and Broker in-house; integrate Sandbox/Runtime kernels</td><td><code>Accepted</code></td><td>Do not build containers/virtualization in-house; requires a unified Sandbox Provider</td></tr><tr><td>ADR-008</td><td>All external side effects go through typed Effects, outbox, idempotency keys, and Receipt</td><td><code>Accepted</code></td><td>Increases implementation complexity but avoids duplication and unauditable actions</td></tr><tr><td>ADR-009</td><td>High-risk actions require Mandate and Approval; an Executor cannot expand permissions</td><td><code>Accepted</code></td><td>Adds interaction but establishes a trust boundary</td></tr><tr><td>ADR-010</td><td>Memory is divided into five categories, with provenance, confidence, sensitivity, budget, and forgetting</td><td><code>Accepted</code></td><td>Requires memory maintenance and a user interface</td></tr><tr><td>ADR-011</td><td>Self-evolution produces only candidate skills, which are promoted after Shadow/Canary/evaluation/rollback</td><td><code>Accepted</code></td><td>Requires evaluation sets and version management</td></tr><tr><td>ADR-012</td><td>Mobile-first PWA; start with viewing/approval/takeover/initiation/notification</td><td><code>Accepted</code></td><td>Do not build a full mobile Agent for now; reduce release costs</td></tr><tr><td>ADR-013</td><td>Token Governor and Context Compiler are core architecture, not afterthought optimizations</td><td><code>Accepted</code></td><td>Requires unified metering, budgeting, and context assembly</td></tr><tr><td>ADR-014</td><td>Learn from OpenClaw/Hermes patterns; do not fork their product foundations</td><td><code>Accepted</code></td><td>Requires building Gateway, Memory, and Evolution protocols in-house</td></tr><tr><td>ADR-015</td><td>Human Executor and takeover are first-class capabilities</td><td><code>Accepted</code></td><td>Requires real-time UI, auditing, and recovery</td></tr><tr><td>ADR-016</td><td>Do not build enterprise multi-tenancy, a public Agent marketplace, or billing</td><td><code>Accepted</code></td><td>Focus on personal experience and self-hosting</td></tr><tr><td>ADR-017</td><td>Currently integrate only Codex; other external Agents are out of product scope for now</td><td><code>Accepted</code> (provisional)</td><td>Retain the Executor interface to avoid lock-in</td></tr><tr><td>ADR-018</td><td>Models are replaceable, local models are optional, and no foundation models are trained</td><td><code>Accepted</code></td><td>Requires a model catalog, routing, and evaluation</td></tr><tr><td>ADR-019</td><td>Adopt MVP-first vertical-slice delivery; the frontend enters every increment starting from Stage 0</td><td><code>Accepted</code></td><td>Backend-first development with the UI added at the end is not allowed; stage acceptance must include browser paths</td></tr><tr><td>ADR-020</td><td>The roadmap advances only by capability gates and increment order, not weekly/monthly schedules</td><td><code>Accepted</code></td><td>No completion dates are promised; progress is measured by real Tasks, recovery, and evaluation evidence</td></tr></tbody></table><hr><h2 id="final-judgment" tabindex="-1">Final Judgment <a class="header-anchor" href="#final-judgment" aria-label="Permalink to &quot;Final Judgment&quot;">​</a></h2><h2 id="final-judgment-1" tabindex="-1">Final Judgment <a class="header-anchor" href="#final-judgment-1" aria-label="Permalink to &quot;Final Judgment&quot;">​</a></h2><p>Back to the original debate: should we write only the control layer and delegate execution to external Agents, or also write the runtime and sandbox entirely ourselves?</p><p><strong>The product roadmap should take the former approach, but it is not a simple “thin wrapper.”</strong></p><p>Hearth builds in-house:</p><ul><li>Control Plane;</li><li>Durable Harness;</li><li>Event Log;</li><li>Approval and idempotency;</li><li>Context Compiler and Token Governor;</li><li>Memory OS;</li><li>Evolution OS;</li><li>Execution Gateway;</li><li>Credential Broker;</li><li>Task cards, approvals, Artifacts, and mobile entry points.</li></ul><p>Hearth integrates:</p><ul><li>Codex;</li><li>Model APIs or local models;</li><li>Container/microVM/Sandbox kernels;</li><li>Playwright;</li><li>Document parsing and conversion libraries;</li><li>Official APIs for email, calendar, cloud storage, and similar services.</li></ul><p>Hearth retains only for learning:</p><ul><li>A minimal event loop and session tree;</li><li>A context compression prototype;</li><li>A single-machine Sandbox wrapper;</li><li>Routing and evaluation experiments.</li></ul><p>This enables deep learning about Agent Runtime, Harness, Sandbox, Gateway, Memory, and Evolution without spending the project&#39;s life reimplementing containers, virtualization, and model inference engines.</p><p>Codex&#39;s positioning should be equally clear:</p><blockquote><p><strong>Codex is currently one of Hearth&#39;s strongest and most general-purpose external Executors. It can write code and also conduct research, produce long documents, reports, spreadsheets, and handle complex file work; but it is not limited to code, nor is it the core of Hearth. Email, calendar, web, desktop, deterministic document processing, and human responsibility are handled by peer Connector, Browser, GUI, Document/Data, and Human Executor components, respectively.</strong></p></blockquote><p>Ultimately, Hearth&#39;s moat is not “having a stronger model,” but:</p><ul><li>Knowing when not to call a model;</li><li>Knowing what minimal context to give an Executor;</li><li>Knowing which actions require whose authorization;</li><li>Knowing how to prove that a Task is truly complete;</li><li>Knowing how to recover after failure;</li><li>Knowing what should be remembered and what should be forgotten;</li><li>Knowing when to stop and return attention to the human.</li></ul><p>If these are achieved, Hearth will be more than an Agent wrapper; it will be a truly personal, long-term reliable digital work system.</p><p>Finally, the delivery judgment:</p><blockquote><p><strong>First build a minimal product that can be used every day in a real browser, then grow it step by step into a Personal Agent OS.</strong></p></blockquote><p>Stage 0 uses a prototype to validate the product narrative; Stage 1 delivers the MVP as early as possible; thereafter, every increment delivers UI, backend, validation, and recovery together. The roadmap sets no development time limits and does not use “which week” to prove progress; it proves the direction is right only through real Tasks, recoverability, and whether users are willing to keep using it.</p>',26)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
